// Pull config, raw body, headers, and normalized source IP into one shape.
const cfg = $('Set - Security Config').first().json;
const req = $('Webhook - Inbound').first().json;

const headers = req.headers || {};

// Prefer X-Forwarded-For (first hop) if present, else the connection IP n8n provides.
let sourceIp = req.ip || 'unknown';
const xff = headers['x-forwarded-for'];
if (xff) {
  sourceIp = xff.split(',')[0].trim();
}

// n8n webhook with rawBody:true exposes the raw body separately from the parsed json body.
const rawBody = req.rawBody !== undefined ? req.rawBody : JSON.stringify(req.body || {});
const parsedBody = req.body || {};

return [{
  json: {
    // config passthrough
    hmacSecret: cfg.hmacSecret,
    signatureHeaderName: cfg.signatureHeaderName,
    signaturePrefix: cfg.signaturePrefix,
    timestampHeaderName: cfg.timestampHeaderName,
    allowedClockSkewSeconds: cfg.allowedClockSkewSeconds,
    rateLimitWindowSeconds: cfg.rateLimitWindowSeconds,
    rateLimitMaxRequests: cfg.rateLimitMaxRequests,
    maxPayloadBytes: cfg.maxPayloadBytes,
    requiredFields: cfg.requiredFields,
    ipAllowList: cfg.ipAllowList,
    failureAlertThreshold: cfg.failureAlertThreshold,
    failureWindowSeconds: cfg.failureWindowSeconds,
    slackSecurityChannel: cfg.slackSecurityChannel,
    auditLogUrl: cfg.auditLogUrl,
    // request data
    sourceIp,
    headers,
    rawBody,
    parsedBody,
    receivedAtIso: new Date().toISOString(),
    receivedAtEpoch: Math.floor(Date.now() / 1000)
  }
}];

// Per-source-IP sliding-window rate limiter using workflow static data.
// Not distributed-safe across multiple n8n instances; swap for Redis at scale.
const item = $input.first().json;
const staticData = $getWorkflowStaticData('node');
if (!staticData.rateBuckets) staticData.rateBuckets = {};

const now = item.receivedAtEpoch;
const windowSec = item.rateLimitWindowSeconds || 60;
const maxReq = item.rateLimitMaxRequests || 60;
const ip = item.sourceIp;

if (!staticData.rateBuckets[ip]) staticData.rateBuckets[ip] = [];

// Drop timestamps outside the window
staticData.rateBuckets[ip] = staticData.rateBuckets[ip].filter(ts => now - ts < windowSec);

// Opportunistic cleanup of stale IP buckets so static data doesn't grow unbounded
const allIps = Object.keys(staticData.rateBuckets);
if (allIps.length > 5000) {
  for (const otherIp of allIps) {
    staticData.rateBuckets[otherIp] = staticData.rateBuckets[otherIp].filter(ts => now - ts < windowSec);
    if (staticData.rateBuckets[otherIp].length === 0) delete staticData.rateBuckets[otherIp];
  }
}

const currentCount = staticData.rateBuckets[ip].length;
const rateLimited = currentCount >= maxReq;

// Only record this attempt if not already over the limit, so we don't let
// a flood keep extending the window indefinitely against itself.
if (!rateLimited) {
  staticData.rateBuckets[ip].push(now);
}

return [{
  json: {
    ...item,
    rateLimited,
    rateLimitCount: currentCount,
    rateLimitMax: maxReq
  }
}];

// Timing-safe HMAC-SHA256 verification over the exact raw body bytes.
const crypto = require('crypto');
const item = $input.first().json;

const secret = item.hmacSecret;
const headerName = (item.signatureHeaderName || 'x-signature-256').toLowerCase();
const prefix = item.signaturePrefix || '';
const incomingSigRaw = (item.headers && item.headers[headerName]) || '';
const incomingSig = prefix && incomingSigRaw.startsWith(prefix)
  ? incomingSigRaw.slice(prefix.length)
  : incomingSigRaw;

let signatureValid = false;
let computedSig = '';

try {
  if (secret && secret !== 'REPLACE_WITH_CREDENTIAL_OR_ENV_SECRET' && incomingSig) {
    computedSig = crypto
      .createHmac('sha256', secret)
      .update(item.rawBody, 'utf8')
      .digest('hex');

    const a = Buffer.from(computedSig, 'utf8');
    const b = Buffer.from(incomingSig, 'utf8');

    // timingSafeEqual requires equal-length buffers; unequal length = invalid,
    // but we still run a comparison of equal length to avoid a trivial timing leak.
    signatureValid = a.length === b.length && crypto.timingSafeEqual(a, b);
  }
} catch (e) {
  signatureValid = false;
}

return [{
  json: {
    ...item,
    signatureValid,
    signaturePresent: !!incomingSig
  }
}];

// Reject stale timestamps (outside allowed clock skew) and reject any
// (signature, timestamp) pair already processed (replay of a captured request).
const crypto = require('crypto');
const item = $input.first().json;
const staticData = $getWorkflowStaticData('node');
if (!staticData.seenNonces) staticData.seenNonces = {};

const tsHeaderName = (item.timestampHeaderName || 'x-request-timestamp').toLowerCase();
const incomingTsRaw = (item.headers && item.headers[tsHeaderName]) || '';
const incomingTs = parseInt(incomingTsRaw, 10);
const skew = item.allowedClockSkewSeconds || 300;

let timestampValid = false;
if (!isNaN(incomingTs)) {
  timestampValid = Math.abs(item.receivedAtEpoch - incomingTs) <= skew;
}

// Nonce = hash of (signature + timestamp) so a captured valid request can't be replayed verbatim.
const sigForNonce = (item.headers && item.headers[(item.signatureHeaderName || '').toLowerCase()]) || '';
const nonceKey = crypto
  .createHash('sha256')
  .update(sigForNonce + '|' + incomingTsRaw)
  .digest('hex');

const now = item.receivedAtEpoch;
let isReplay = false;
if (sigForNonce && incomingTsRaw) {
  if (staticData.seenNonces[nonceKey]) {
    isReplay = true;
  } else {
    staticData.seenNonces[nonceKey] = now;
  }
}

// Cleanup: drop nonces older than the skew window (they'd fail timestampValid anyway).
const nonceKeys = Object.keys(staticData.seenNonces);
if (nonceKeys.length > 20000) {
  for (const k of nonceKeys) {
    if (now - staticData.seenNonces[k] > skew * 2) delete staticData.seenNonces[k];
  }
}

return [{
  json: {
    ...item,
    timestampValid,
    isReplay,
    timestampPresent: !isNaN(incomingTs)
  }
}];

// Structural validation independent of business logic: required fields,
// basic types, and a hard size cap to blunt oversized-payload DoS attempts.
const item = $input.first().json;

const required = (item.requiredFields || '')
  .split(',')
  .map(s => s.trim())
  .filter(Boolean);

const body = item.parsedBody || {};
const missingFields = required.filter(f => body[f] === undefined || body[f] === null || body[f] === '');

const bodySizeBytes = Buffer.byteLength(item.rawBody || '', 'utf8');
const maxBytes = item.maxPayloadBytes || 200000;
const payloadTooLarge = bodySizeBytes > maxBytes;

const schemaValid = missingFields.length === 0 && !payloadTooLarge;

return [{
  json: {
    ...item,
    schemaValid,
    missingFields,
    bodySizeBytes,
    payloadTooLarge
  }
}];

// Optional CIDR-aware IP allow-list. If ipAllowList is empty, this gate always passes.
const item = $input.first().json;

function ipToInt(ip) {
  const parts = ip.split('.').map(Number);
  if (parts.length !== 4 || parts.some(p => isNaN(p) || p < 0 || p > 255)) return null;
  return ((parts[0] << 24) | (parts[1] << 16) | (parts[2] << 8) | parts[3]) >>> 0;
}

function ipInCidr(ip, cidr) {
  if (!cidr.includes('/')) return ip === cidr;
  const [range, bitsStr] = cidr.split('/');
  const bits = parseInt(bitsStr, 10);
  const ipInt = ipToInt(ip);
  const rangeInt = ipToInt(range);
  if (ipInt === null || rangeInt === null) return false;
  const mask = bits === 0 ? 0 : (~0 << (32 - bits)) >>> 0;
  return (ipInt & mask) === (rangeInt & mask);
}

const allowListRaw = (item.ipAllowList || '').trim();
let ipAllowed = true;

if (allowListRaw) {
  const entries = allowListRaw.split(',').map(s => s.trim()).filter(Boolean);
  ipAllowed = entries.some(entry => ipInCidr(item.sourceIp, entry));
}

return [{
  json: {
    ...item,
    ipAllowed,
    ipAllowListConfigured: !!allowListRaw
  }
}];

// Single source of truth for pass/fail + a specific reason code, used by
// both the audit log and the HTTP response.
const item = $input.first().json;

let passed = true;
let reason = 'OK';
let httpStatus = 200;

if (item.rateLimited) {
  passed = false; reason = 'RATE_LIMITED'; httpStatus = 429;
} else if (!item.signaturePresent) {
  passed = false; reason = 'MISSING_SIGNATURE'; httpStatus = 401;
} else if (!item.signatureValid) {
  passed = false; reason = 'BAD_SIGNATURE'; httpStatus = 401;
} else if (!item.timestampPresent) {
  passed = false; reason = 'MISSING_TIMESTAMP'; httpStatus = 400;
} else if (item.isReplay) {
  passed = false; reason = 'REPLAY_DETECTED'; httpStatus = 401;
} else if (!item.timestampValid) {
  passed = false; reason = 'EXPIRED_TIMESTAMP'; httpStatus = 401;
} else if (item.payloadTooLarge) {
  passed = false; reason = 'PAYLOAD_TOO_LARGE'; httpStatus = 413;
} else if (!item.schemaValid) {
  passed = false; reason = 'SCHEMA_INVALID'; httpStatus = 400;
} else if (!item.ipAllowed) {
  passed = false; reason = 'IP_BLOCKED'; httpStatus = 403;
}

return [{
  json: {
    ...item,
    securityPassed: passed,
    securityReason: reason,
    httpStatus
  }
}];

// Per-IP rolling failure counter, used to detect brute-force / probing behavior
// that individually stays under the rate limit (e.g. slow signature guessing).
const item = $input.first().json;
const staticData = $getWorkflowStaticData('node');
if (!staticData.failureLog) staticData.failureLog = {};

const ip = item.sourceIp;
const now = item.receivedAtEpoch;
const windowSec = item.failureWindowSeconds || 300;
const threshold = item.failureAlertThreshold || 5;

if (!staticData.failureLog[ip]) staticData.failureLog[ip] = [];
staticData.failureLog[ip] = staticData.failureLog[ip].filter(ts => now - ts < windowSec);
staticData.failureLog[ip].push(now);

const failureCount = staticData.failureLog[ip].length;
const alertThresholdExceeded = failureCount >= threshold;

// Reset the streak once we alert, so we don't spam Slack every single request after threshold.
if (alertThresholdExceeded) {
  staticData.failureLog[ip] = [];
}

return [{
  json: {
    ...item,
    failureCount,
    alertThresholdExceeded
  }
}];
